package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec
var inputLines []string
var inputIdx int

func fitDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep low-order digits that fit; high-order truncation
	// working with positive numbers only in this program
	if v.IsNegative() {
		// for completeness handle negative via positive then restore sign
		pos := v.Abs()
		f := fitDecimal(pos, intDigits, scale)
		return f.Neg()
	}
	// ensure truncated to scale (caller already did rounding/truncation as needed)
	// convert to integer units
	// Shift scale to get integer
	shifted := v.Shift(scale) // v * 10^scale
	// truncated toward zero integer part
	iv := shifted.Truncate(0)
	// modulus = 10^(intDigits+scale)
	mod := decimal.NewFromInt(1).Shift(int32(intDigits) + scale)
	// iv % mod
	rem := iv.Mod(mod)
	// rebuild
	return rem.Shift(-scale)
}

func formatEdited(val decimal.Decimal, pic string) string {
	parts := strings.Split(pic, ".")
	intPic := parts[0]
	fracPic := ""
	if len(parts) > 1 {
		fracPic = parts[1]
	}
	scale := len(fracPic)

	// truncate to scale (MOVE does not round)
	v := val.Truncate(int32(scale))

	s := v.StringFixed(int32(scale))
	// handle sign - not needed for this program, but keep
	sign := ""
	if strings.HasPrefix(s, "-") {
		sign = "-"
		s = s[1:]
		_ = sign
	}

	var intStr, fracStr string
	if scale > 0 {
		idx := strings.Index(s, ".")
		if idx >= 0 {
			intStr = s[:idx]
			fracStr = s[idx+1:]
			// pad fracStr
			if len(fracStr) < scale {
				fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
			} else if len(fracStr) > scale {
				fracStr = fracStr[:scale]
			}
		} else {
			intStr = s
			fracStr = strings.Repeat("0", scale)
		}
	} else {
		if idx := strings.Index(s, "."); idx >= 0 {
			intStr = s[:idx]
		} else {
			intStr = s
		}
		if intStr == "" {
			intStr = "0"
		}
	}

	// count placeholders in intPic
	maxDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			maxDigits++
		}
	}
	// high-order truncation: keep low-order maxDigits digits
	if len(intStr) > maxDigits {
		intStr = intStr[len(intStr)-maxDigits:]
	}
	// left pad with zeros to maxDigits
	if len(intStr) < maxDigits {
		intStr = strings.Repeat("0", maxDigits-len(intStr)) + intStr
	}
	// intStr now exactly maxDigits

	// build int part formatting
	intRunes := []rune(intPic)
	outInt := make([]rune, len(intRunes))
	placeholderIdx := 0
	suppress := true
	for i, ch := range intRunes {
		if ch == ',' {
			if suppress {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			digit := intStr[placeholderIdx]
			placeholderIdx++
			if suppress {
				if digit == '0' && ch == 'Z' {
					outInt[i] = ' '
					// stay suppressed
				} else {
					outInt[i] = rune(digit)
					suppress = false
				}
			} else {
				outInt[i] = rune(digit)
			}
		} else {
			outInt[i] = ch
		}
	}
	intPart := string(outInt)
	if scale > 0 {
		return intPart + "." + fracStr
	}
	return intPart
}

func formatCount(v int64) string {
	// PIC 99 zero padded 2 digits, high-order truncation
	rv := v % 100
	if rv < 0 {
		rv += 100
	}
	return fmt.Sprintf("%02d", rv)
}

func parseLine(line string) OrderRec {
	// pad to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	orId := line[0:5]
	orStat := line[5:6]
	qtyStr := line[6:9]
	priceStr := line[9:15]

	var qty int64 = 0
	qs := strings.TrimSpace(qtyStr)
	if qs != "" {
		// parse digits, ignoring leading spaces already trimmed
		// if contains non-digit, treat as 0 (not needed)
		var n int64
		for _, c := range qs {
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			}
		}
		// But original PIC 9(3) expects exactly 3 digits; simple atoi of trimmed string works for leading zeros
		// Use parsed n but need to handle case where qs is e.g., "001" -> n=1 ok
		// For strings with spaces inside? not needed
		qty = n
		// Alternatively if qs is like " 12", we already parsed 12; ok
		// If line had spaces leading, TrimSpace removed them
	}

	priceStrTrim := strings.TrimSpace(priceStr)
	var price decimal.Decimal
	if priceStrTrim == "" {
		price = decimal.NewFromInt(0)
	} else {
		// priceStr is 6 digits, may contain spaces? Keep only digits
		digits := ""
		for _, c := range priceStr {
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits == "" {
			price = decimal.NewFromInt(0)
		} else {
			// parse as integer
			// Use decimal.NewFromString with shift
			// Convert via int64 if fits, else via decimal
			d, _ := decimal.NewFromString(digits)
			price = d.Shift(-2)
		}
	}

	return OrderRec{
		OrId:    orId,
		OrStat:  orStat,
		OrQty:   qty,
		OrPrice: price,
	}
}

func MainPara() {
	// OPEN INPUT
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		// increase buffer for long lines if needed
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			// Scanner strips \n and \r ; keep as is (without newline)
			line := scanner.Text()
			// Remove possible \r already stripped by Scan? but keep
			inputLines = append(inputLines, line)
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		f.Close()
	}

	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE - no op
	SummaryPara()
}

func ReadPara() {
	if inputIdx < len(inputLines) {
		orderRec = parseLine(inputLines[inputIdx])
		inputIdx++
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsTotal = decimal.NewFromInt(0)

	if orderRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE (truncated)
		raw := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice)
		raw = raw.Truncate(2)
		WsTotal = fitDecimal(raw, 8, 2)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if orderRec.OrStat == "S" {
		raw := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(decimal.NewFromFloat(1.05))
		// Actually use exact decimal for 1.05
		// NewFromFloat may introduce binary error, so use string
		raw = decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(decimal.RequireFromString("1.05"))
		raw = raw.Round(2)
		WsTotal = fitDecimal(raw, 8, 2)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if orderRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}

	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = fitDecimal(WsGrand.Truncate(2), 10, 2)

	ReadPara()
}

func ShowPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SummaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatCount(WsNewCount), formatCount(WsShipCount), formatCount(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatCount(WsInvalid), formatCount(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	MainPara()
}
